from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class File_download(EmssimCommand):
    def __init__(self, method="file_download", timeout=60, rpc_connection_name='localRPC'):
        super(File_download, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(File_download, self).on_new_data(**data)
        if "msg" in data:
            if (data["msg"] == "Validation completed, activating plan file"):
                self._ret['validation'] = "completed"
            elif (data["msg"] == "Activation completed"):
                self._ret['activation'] = "completed"
            elif (data["msg"] == "Validation Errors"):
                self._ret['error_table'] = data["tables"]
                self._ret['verror'] = []
                for arr in data["tables"]:
                    for tup in arr:
                        self._ret['verror'].append(tup["TEXT"])
        elif ("status" in data):
            self._ret["status"] = data["status"]
